// js/xp.js
function xpForLevel(l) {
  return XP_TABLE[Math.max(1, Math.min(MAX_LEVEL, l))];
}
function levelForXp(xp2) {
  for (let l = MAX_LEVEL; l >= 1; l--)
    if (xp2 >= XP_TABLE[l])
      return l;
  return 1;
}
function combatLevel(lv) {
  const prayer = lv.prayer || 1, magic = lv.magic || 1;
  const base2 = 0.25 * (lv.defence + lv.hitpoints + Math.floor(prayer / 2));
  const melee = 0.325 * (lv.attack + lv.strength);
  const range = 0.325 * Math.floor(lv.ranged * 1.5);
  const mage = 0.325 * Math.floor(magic * 1.5);
  return Math.floor(base2 + Math.max(melee, range, mage));
}
