function buyHorse() {
  if (G.ownedHorse) {
    msg("You already own a horse.");
    return;
  }
  if (G.coins < HORSE_PRICE) {
    msg(`A horse costs ${HORSE_PRICE} coins.`);
    return;
  }
  G.coins -= HORSE_PRICE;
  emit("coins");
  G.ownedHorse = true;
  if (!invHas("horse_deed"))
    invAdd("horse_deed", 1);
  summonFollowHorse();
  addXp("riding", 25);
  msg("Ellie May sells you a sturdy quarter horse. Talk to it to Mount.");
}
